import datetime
from _shared import bearer, request_json
MANIFEST={"apiVersion":1,"id":"fitbit","name":"Fitbit Daily Activity","description":"Show daily Fitbit activity totals such as steps, distance, calories, floors, and active minutes.","version":"1.0","icon":"♥","refreshMin":15,"kind":"status","settings":[{"key":"accessToken","label":"Access token","type":"password"},{"key":"refreshToken","label":"Refresh token","type":"password"},{"key":"clientId","label":"Fitbit client ID","type":"text"},{"key":"clientSecret","label":"Fitbit client secret","type":"password"},{"key":"date","label":"Date (YYYY-MM-DD or today)","type":"text","default":"today"}]}
MANIFEST.update({'access': 'account', 'dataFlow': 'provider-cloud', 'dataLeavesDevice': True, 'privacyNote': 'LibreDisplay sends authenticated fitness-data requests to Fitbit over HTTPS and receives activity summaries.', 'freedomAlternative': 'No equivalent bundled local/self-hosted fitness provider yet.'})
def _token(s,c): return bearer(s,c,token_url='https://api.fitbit.com/oauth2/token',form={'client_id':s.get('clientId')},cache_prefix='fitbit',basic=(s.get('clientId'),s.get('clientSecret')) if s.get('clientId') and s.get('clientSecret') else None)
def fetch(s,c):
 token=_token(s,c); date=str(s.get('date') or 'today').strip(); url=f'https://api.fitbit.com/1/user/-/activities/date/{date}.json'; data,_,_=request_json(c,url,headers={'Authorization':'Bearer '+token,'User-Agent':'LibreDisplay integration'}); sm=data.get('summary') or {}; steps=sm.get('steps')
 return {'kind':'status','provider':'Fitbit','title':'Fitbit activity','value':steps if steps is not None else '—','suffix':' steps','details':[{'label':'Calories','value':sm.get('caloriesOut')},{'label':'Distance','value':sum(float(x.get('distance') or 0) for x in (sm.get('distances') or []) if x.get('activity')=='total')},{'label':'Floors','value':sm.get('floors')},{'label':'Active min','value':sum(int(sm.get(k) or 0) for k in ('fairlyActiveMinutes','veryActiveMinutes'))}]}
